Program Answer;
{$H+}
Uses sysutils, classes, math;

Type
  TCard = String[2];
  TDeck = Array Of TCard;

Var
  StartDeck, FinalDeck: TDeck;
  N: Int32;

Procedure CalculateStartDeck;
Var
  aIndex: integer;

  Function getNextFreeIndex: integer;
  Begin
    getNextFreeIndex := aIndex;
    // First Hit = "empty"
    While StartDeck[getNextFreeIndex] <> #0#0 Do Begin
      getNextFreeIndex := (getNextFreeIndex + 1) Mod N;
    End;
    getNextFreeIndex := (getNextFreeIndex + 1) Mod N;
    // Second Hit = "NextIndex"
    While StartDeck[getNextFreeIndex] <> #0#0 Do Begin
      getNextFreeIndex := (getNextFreeIndex + 1) Mod N;
    End;
  End;  

Var
  i: Integer;
Begin
  aIndex := 0;
  For i := 0 To N - 1 Do Begin
    StartDeck[aIndex] := FinalDeck[i];
    If i <> N - 1 Then Begin
      aIndex := getNextFreeIndex;
    End;
  End;
End;

Var

  Line, input: String;
  i: Integer;

Begin
  // Read in Values and convert to deck
  readln(line);
  N := StrToInt(line);
  readln(input);
  setlength(FinalDeck, N);
  For i := 0 To n - 1 Do Begin
    FinalDeck[i] := copy(input, 1 + i * 3, 2);
  End;
  // Init Start Deck
  setlength(StartDeck, N);
  For i := 0 To n - 1 Do Begin
    StartDeck[i] := #0#0;
  End;
  CalculateStartDeck;
  Line := '';
  For i := 0 To n - 1 Do Begin
    line := line + StartDeck[i];
    if i <> n - 1 then line := line + ' ';
  End;
  writeln(line);
  flush(StdErr); flush(output); // DO NOT REMOVE
End.
